import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = re.compile(r'https?://[^\s]+')
    urls = re.findall(url_pattern, myString)
    result = {}
    for url in urls:
        domain = urllib.parse.urlparse(url).hostname
        if not domain:
            result[domain] = None
            continue
        api_url = f'http://ip-api.com/json/{domain}?access_key={API_KEY}'
        try:
            response = requests.get(api_url, timeout=5)
            data = json.loads(response.text)
            if data.get('status') == 'success':
                result[domain] = data
            else:
                result[domain] = None
        except:
            result[domain] = None
    return result

