import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Malformed JSON data")
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data must be a non-empty list")
    countries = []
    populations = []
    for entry in data:
        if not isinstance(entry, dict):
            raise ValueError("Each entry must be a dictionary")
        if 'Country' not in entry or 'Population' not in entry:
            raise ValueError("Missing 'Country' or 'Population' key")
        country = entry['Country']
        population = entry['Population']
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if population < 0:
            raise ValueError("Population cannot be negative")
        population = math.floor(float(population))
        countries.append(country)
        populations.append(population)
    df = pd.DataFrame({'Country': countries, 'Population': populations})
    try:
        os.makedirs(output_dir, exist_ok=True)
        output_path = os.path.join(output_dir, file_name)
        df.to_csv(output_path, index=False)
    except (IOError, OSError):
        raise IOError("Cannot write to the specified directory")
    return output_path, df

